const recruitingTeams=[['CHA-T','🐳','CH_Alpha'],['CHO-T','🐬','CH_Omega'],['DC-T','🍄','Equipe Discord'],['MT-T','😈','Equipe Mentoria'],['REC-T','😡','Equipe Rec'],['EvT-T','🐈‍⬛','Equipe Eventos'],['RES-T','🎊','Equipe Resenha'],['FxF-T','🐯','Equipe FacxFac'],['AC-T','✨','Equipe ações'],['AZA-T','🐺','Equipe AZ_Alpha'],['AZD-T','🦊','Equipe AZ_Delta'],['AZO-T','🦇','Equipe AZ_Omega'],['TKA-T','🔥','Equipe Tickets_Alpha'],['TKD-T','🌙','Equipe Tickets_Delta']];
const recruitingTeam = tag => recruitingTeams.find(([id])=>id===tag);
const candidateDisplay = item => {const t=recruitingTeam(item.team);return `${t?`${t[0]} | ${t[1]} `:''}${item.candidateName}${t?` | ${item.passport}`:''}`;};
const recruitmentLog = item => {const t=recruitingTeam(item.team),tag=t?.[0]||item.team||'—',discordId=(item.recruiterDiscordId||'').replace(/\D/g,'');return `${t?`${t[0]} | ${t[1]} `:''}${item.candidateName}${t?` | ${item.passport}`:''}\nRecrutador: ${discordId?`<@${discordId}>`:item.recruiter}\nRecrutado: ${item.candidateName}\nid: ${item.passport}\nidade: ${item.age||'—'}\nDisponibilidade: ${(item.availability||[]).join(', ')||'—'}\nhoras in-game: ${item.hoursInGame??item.playTime??'—'}\nPasta: ${tag}`;};
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const api = async (path, body, method) => { const r = await fetch('/api' + path, { method:method || (body ? 'POST' : 'GET'), headers:body ? {'Content-Type':'application/json'} : {}, body:body ? JSON.stringify(body) : undefined }); const data = await r.json(); if (!r.ok) throw Error(data.error || 'Não foi possível concluir a ação.'); return data; };
