const themePresets = { 'Geovanna Bellmont':{accent:'#c35bd6',background:'#10091a',panel:'#1a1025',text:'#f3eafa'}, 'Gabriel Pokas Dev':{accent:'#bd55d4',background:'#10091a',panel:'#1b1028',text:'#f7edfb'}, 'Verde original':{accent:'#a6f36b',background:'#0b0d11',panel:'#12151b',text:'#f3f5f8'}, 'Azul noturno':{accent:'#72b7ff',background:'#08111d',panel:'#101c2a',text:'#edf5ff'} };
