function toast(msg) { const el=document.createElement('div'); el.className='toast'; el.textContent=msg; document.body.append(el); setTimeout(()=>el.remove(),2800); }
function field(label,name,type='text',placeholder='',value='',required=true) { return `<div class="field"><label>${label}</label><input name="${name}" type="${type}" placeholder="${placeholder}" value="${esc(value)}" ${required?'required':''}></div>`; }
function fail(el,msg) { const target=typeof el==='string'?document.querySelector(el):el; if(target) target.innerHTML=`<div class="alert">${esc(msg)}</div>`; }
const auditLabels={candidate:'Candidato',team:'Equipe',passport:'Passaporte',age:'Idade',availability:'Disponibilidade',hoursInGame:'Horas in-game',recruiterDiscordId:'Discord do recrutador',status:'Status',reason:'Motivo',name:'Nome',username:'Login',role:'Cargo',from:'Cargo anterior',to:'Cargo novo',completed:'Tarefas concluídas',average:'Média',kind:'Tipo',category:'Categoria',points:'Pontos',date:'Data',roles:'Cargos afetados',id:'Registro'};
function renderAudit(items,title='Histórico operacional',description='Ações do sistema organizadas por data, com responsável e detalhes.') {
  const dateKey=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
  const today=new Date();today.setHours(0,0,0,0);const todayKey=dateKey(today);
  const todayCount=items.filter(x=>{const d=new Date(x.timestamp);d.setHours(0,0,0,0);return d.getTime()===today.getTime()}).length;
  const actions=[...new Set(items.map(x=>x.action))].sort((a,b)=>a.localeCompare(b,'pt-BR'));
  const groups=items.reduce((all,x)=>{const key=dateKey(new Date(x.timestamp));(all[key]||=[]).push(x);return all;},{});
  const rows=Object.entries(groups).sort(([a],[b])=>b.localeCompare(a)).map(([key,entries])=>`<section class="audit-day"><div class="audit-day-title">${key===todayKey?'Hoje':new Date(`${key}T12:00:00`).toLocaleDateString('pt-BR',{weekday:'long',day:'2-digit',month:'long',year:'numeric'})}<span>${entries.length} ${entries.length===1?'operação':'operações'}</span></div><div class="audit-list">${entries.map(x=>{const details=Object.entries(x.details||{}).map(([k,v])=>`<span class="audit-detail"><small>${esc(auditLabels[k]||k)}</small><b>${esc(Array.isArray(v)?v.join(', '):v&&typeof v==='object'?JSON.stringify(v):v)}</b></span>`).join('');return`<article class="audit-entry"><div class="audit-marker">${esc((x.action||'?').slice(0,1).toUpperCase())}</div><div class="audit-content"><div class="audit-entry-head"><div><b>${esc(x.action)}</b><span class="role">${esc(roles[x.role]||x.role||'Sistema')}</span></div><time>${new Date(x.timestamp).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</time></div><div class="audit-actor">Responsável: <strong>${esc(x.actor||'Sistema')}</strong></div>${details?`<div class="audit-details">${details}</div>`:''}</div></article>`}).join('')}</div></section>`).join('');
  return `${header(title,description)}<section class="stats audit-stats">${stat('Operações visíveis',items.length,'Conforme seu nível de acesso')}${stat('Registradas hoje',todayCount,'Atividade recente')}</section><section class="card section audit-panel"><div class="audit-toolbar"><div><b>Registro de atividades</b><p class="muted">Cada registro é somente leitura e mantém quem fez a ação e quando.</p></div><div class="audit-filters"><input id="audit-search" placeholder="Buscar ação, pessoa ou detalhe"><select id="audit-action"><option value="">Todas as operações</option>${actions.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div></div><div id="audit-feed">${rows||'<div class="empty">Nenhuma operação registrada neste período.</div>'}</div></section>`;
}
function bindAuditFilters(){const search=document.querySelector('#audit-search'),action=document.querySelector('#audit-action'),feed=document.querySelector('#audit-feed');if(!search||!action||!feed)return;const apply=()=>{const q=search.value.trim().toLocaleLowerCase('pt-BR'),kind=action.value;feed.querySelectorAll('.audit-entry').forEach(row=>{row.hidden=(kind&&!row.querySelector('.audit-entry-head b')?.textContent.includes(kind))||(q&&!row.textContent.toLocaleLowerCase('pt-BR').includes(q))});feed.querySelectorAll('.audit-day').forEach(day=>day.hidden=!day.querySelector('.audit-entry:not([hidden])'))};search.oninput=apply;action.onchange=apply;}

function renderSetup() {
  app.innerHTML=`<section class="auth">${brand}<div class="eyebrow">Configuração inicial · acesso master</div><h1>Login Staff da Nobre</h1><p class="sub">Cadastre uma conta de desenvolvedor com nome e senha.</p><form id="setup">${field('Nome','name','text','','Geovanna')}${field('Senha','password','password','Digite a senha')}<button class="btn primary wide">Criar acesso</button></form><p class="hint setup-note">Use pelo menos 8 caracteres. A senha será protegida e não ficará no código.</p><div id="error"></div></section>`;
  document.querySelector('#setup').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/setup',{developers:[{name:f.get('name'),password:f.get('password')}]});toast('Acesso criado. Faça login.');renderLogin()}catch(err){fail('#error',err.message)}};
}
function renderLogin() {
  app.innerHTML=`<section class="auth">${brand}<div class="eyebrow">Painel administrativo</div><h1>Login Staff da Nobre</h1><p class="sub">Entre com seu nome e sua senha.</p><form id="login">${field('Nome','name','text','Seu nome')}${field('Senha','password','password','Sua senha')}<button class="btn primary wide">Entrar no painel</button></form><div id="error"></div><p class="hint" style="margin-top:20px">Acesso restrito a usuários autorizados.</p></section>`;
  document.querySelector('#login').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/login',{name:f.get('name'),password:f.get('password')});await renderApp()}catch(err){fail('#error',err.message)}};
}
